inline auto glyph(UiTextFont::Kind kind, uint32_t codepoint) -> const UiTextFont::Glyph* {
    const Entry* table = nullptr;
    uint8_t count = 0;
    switch (kind) {
        case UiTextFont::Kind::Large:
            table = ENTRIES_LARGE;
            count = sizeof(ENTRIES_LARGE) / sizeof(ENTRIES_LARGE[0]);
            break;
        case UiTextFont::Kind::Small:
            table = ENTRIES_SMALL;
            count = sizeof(ENTRIES_SMALL) / sizeof(ENTRIES_SMALL[0]);
            break;
        default:
            return nullptr;
    }
    static UiTextFont::Glyph match{};
    for (uint8_t i = 0; i < count; ++i) {
        Entry entry{};
        memcpy_P(&entry, &table[i], sizeof(Entry));
        if (entry.codepoint != codepoint) continue;
        match = entry.glyph;
        return &match;
    }
    return nullptr;
}

